  'datacentre-hall': [10, 9, 23],
  'chiller-block': [3.1, 3, 3.1],
  'shipping-container': [2.4, 2.6, 5.6],
  'pylon-tower': [6.4, 24, 11.1],
  'overpass-segment': [5.9, 9, 8.5],
  'rubble-slab': [6, 1.5, 5],
