const FALLBACK_COLOUR: Readonly<Record<string, string>> = {
  'datacentre-hall': '#353f49', 'chiller-block': '#4c5864', 'shipping-container': '#3d4c59', 'pylon-tower': '#36404a',
  'overpass-segment': '#454b52', 'rubble-slab': '#42464b',
